{
  "constraints": [
    {
      "constraint": "若画面呈现车辆侧面或整体轮廓，车身应为四门轿车，而非 SUV、MPV、皮卡或双门跑车。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现车辆前脸，前脸不得出现传统燃油车的大面积开放式进气格栅。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现车辆后部或车底，不得出现传统排气尾管或排气管。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面呈现中控台区域，应有一块明显的大尺寸中央触控屏。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "若画面中可见品牌标识，应为特斯拉品牌标识（T 形徽标或 Tesla 字标），而非其他品牌标识。",
      "polarity": "must_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "若画面中可见车门把手，门把手不得为传统外凸式门把手。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    }
  ]
}
